\caption{MLGD outer loop (black-box loss)}
\label{alg:mlgd-outer}

\raggedright
\textbf{Input:} Pretrained score network $s_\theta$ for $\mathcal{P}(X)$;
black-box loss $\mathcal{L}: \mathcal{X} \to \mathbb{R}$;
noise schedule $\{\bar{\alpha}_t\}_{t=1}^T$;
guidance strengths $\{\zeta_t\}_{t=1}^T$.\\
\textbf{Output:} Sample $x_0$ guided toward $\mathcal{G}$.\\[3pt]
\begin{algorithmic}[1]
\State $x_T \sim \mathcal{N}(0, I)$
\For{$t = T, T{-}1, \ldots, 1$}
  \State $\hat{x}_0 \leftarrow \tfrac{1}{\sqrt{\bar{\alpha}_t}}\bigl(x_t + (1-\bar{\alpha}_t)\,s_\theta(x_t,t)\bigr)$
    \Comment{Tweedie estimate}
  \State $x_{t-1} \leftarrow \textsc{DDIM\_step}(x_t, s_\theta, t)\;-\;\zeta_t\,\nabla_{x_t}\mathcal{L}(\hat{x}_0)$
    \Comment{Denoising step $-$ inner-estimator guidance (Alg.~\ref{alg:inner-estimator})}
\EndFor
\State \Return $x_0$
\end{algorithmic}

\caption{Inner estimator for $\mathcal{L}(x)$ (our contribution)}
\label{alg:inner-estimator}

\raggedright
\textbf{Input:} Query conditioning $x$; pretrained differentiable sampler $f_\phi$ for $\mathcal{P}(Y{\mid}X)$;
target sample $\mathcal{S}_{\mathcal{G}} \sim \mathcal{G}$; number of conditional samples $n_{\mathrm{cond}}$; distributional distance $\mathcal{L}$ (e.g.\ MMD, SWD).\\
\textbf{Output:} Estimate $\widehat{\mathcal{L}}(x)$ and its gradient $\nabla_x \widehat{\mathcal{L}}(x)$.\\[3pt]
\begin{algorithmic}[1]
\State Sample internal noise $\eta_1, \ldots, \eta_{n_{\mathrm{cond}}} \stackrel{\text{iid}}{\sim} \pi$
\State $\mathcal{S}_{\mathrm{cond}} \leftarrow \{f_\phi(x, \eta_i)\}_{i=1}^{n_{\mathrm{cond}}}$
  \Comment{Fast conditional samples; differentiable in $x$}
\State $\widehat{\mathcal{L}}(x) \leftarrow \mathcal{L}\bigl(\mathcal{S}_{\mathrm{cond}},\, \mathcal{S}_{\mathcal{G}}\bigr)$
  \Comment{Plug-in distributional-loss estimator}
\State $\nabla_x \widehat{\mathcal{L}}(x) \leftarrow \textsc{autograd}(\widehat{\mathcal{L}}(x),\, x)$
  \Comment{Backprop through $f_\phi$}
\State \Return $\widehat{\mathcal{L}}(x),\; \nabla_x \widehat{\mathcal{L}}(x)$
\end{algorithmic}

