\caption{MLGD-F{} Conditional Sampling (full detailed version)}
\label{alg:mlgd-d-full}
\footnotesize
\raggedright
\textbf{Input:}
Pretrained score network $s_\theta$ for $\mathcal{P}(X)$;
pretrained few-step model $f_\phi$ for $\mathcal{P}(Y|X)$;
target distribution $\mathcal{G}$;
drift function $f(x,t)$;
diffusion coefficient $g(t)$;
noise schedule $\{\bar{\alpha}_t\}_{t=1}^T$;
step-size schedule $\{\zeta_t\}$ (e.g.\ $\zeta_t = \zeta' / \|\nabla \mathcal{L}\|$
as in~\citep{DiffusionPosteriorSampling}, with $\zeta'$ proportional to $\beta$).\\
\textbf{Parameters:}
Total timesteps $T$;
step size $\Delta t = 1/T$;
inverse temperature $\beta \ge 0$ (target is
$\mathcal{Q}_\beta(x) \propto \mathcal{P}(x)\, e^{-\beta\mathcal{L}(x)}$;
$\beta=0$ samples from $\mathcal{P}$, $\beta\to\infty$ concentrates at
$\arg\min_x \mathcal{L}$);
MC samples $n_{\text{MC}}$ (number of perturbed $\hat{x}_0$ estimates used to stabilize the gradient);
conditional samples $n_{\text{cond}}$ (samples drawn from $\mathcal{P}(Y|X)$ per candidate);
target samples $n_{\text{target}}$ (samples drawn from $\mathcal{G}$);
distributional loss $\mathcal{L}$ (e.g.\ MMD, SWD).\\
\textbf{Output:} Sample $x_0$ approximately drawn from $\mathcal{Q}_\beta$\\[4pt]
\begin{algorithmic}[1]
\State $S_{\mathcal{G}} \leftarrow \{\tilde y_1, \ldots, \tilde y_{n_{\text{target}}}\} \sim \mathcal{G}$
  \Comment{Sample target distribution once}
\State $x_T \sim \mathcal{N}(0, I)$
\For{$i = 0, \ldots, T-1$}
  \State $t \leftarrow 1 - i \cdot \Delta t$
  \State $\hat{x}_0 \leftarrow \tfrac{1}{\sqrt{\bar{\alpha}_t}}
    \bigl(x_t + (1-\bar{\alpha}_t)\,s_\theta(x_t,t)\bigr)$
    \Comment{Tweedie estimate of $x_0$}
  \State $\{\hat{x}_0^{(i)}\}_{i=1}^{n_{\text{MC}}} \sim
    \mathcal{N}\!\left(\hat{x}_0,\; \tfrac{g(t)}{\sqrt{1+g(t)^2}}\,I\right)$
    \Comment{MC perturbations around $\hat{x}_0$}
  \For{$i = 1, \ldots, n_{\text{MC}}$}
    \State $S_{Y|X}^{(i)} \leftarrow \{y_1^{(i)}, \ldots, y_{n_{\text{cond}}}^{(i)}\}
      \sim \mathcal{P}(Y \mid X{=}\hat{x}_0^{(i)})$ \textbf{using} $f_\phi$
      \Comment{Fast conditional samples}
    \State $\mathcal{L}^{(i)} \leftarrow \mathcal{L}(S_{Y|X}^{(i)},\, S_{\mathcal{G}})$
      \Comment{Distributional loss against target}
  \EndFor
  \State $\nabla_{x_t}\mathcal{L} \leftarrow -\nabla_{x_t}
    \log\!\left(\tfrac{1}{n_{\text{MC}}}\sum_{i=1}^{n_{\text{MC}}}
    \exp\!\left(-\mathcal{L}^{(i)}\right)\right)$
    \State $\Delta x_t \leftarrow -\bigl[f(x_t,t) - g(t)^2\,s_\theta(x_t,t)\bigr]\Delta t
    + g(t)\sqrt{\Delta t}\,\epsilon$
    \Comment{Standard denoising step}
  \State $x_{t-1} \leftarrow x_t + \Delta x_t - \zeta_t\,\nabla_{x_t}\mathcal{L}$
    \Comment{Denoising + guidance}
\EndFor
\State \Return $x_0$
\end{algorithmic}

\label{ass:diff}
$f_\phi(x,\eta)$ is almost surely differentiable in $x$ with
$\mathbb{E}_\eta\,\|\partial_x f_\phi(x,\eta)\|^2 \le C_f^2 < \infty$.

Write $n := n_{\mathrm{cond}}$ and $m := n_{\mathrm{target}}$. By the
triangle inequality,
\begin{equation}
  \bigl|\widehat{\mathcal{L}}_\phi(x) - \mathcal{L}(x)\bigr|
    \;\le\;
    \underbrace{\bigl|\widehat{\mathcal{L}}_\phi(x)
                     - \mathcal{L}_\phi(x)\bigr|}_{T_1\ \text{(Monte Carlo)}}
    \;+\;
    \underbrace{\bigl|\mathcal{L}_\phi(x) - \mathcal{L}(x)\bigr|}_{T_2\ \text{(distillation)}},
  \label{eq:loss-triangle}
\end{equation}
and we bound $T_1, T_2$ separately.

\emph{Step 1: Monte Carlo term.}
The unbiased two-sample U-statistic estimator
$\widehat{\operatorname{MMD}}^2_U$ satisfies
$\mathbb{E}[\widehat{\mathcal{L}}_\phi(x)] = \mathcal{L}_\phi(x)$ and
expands as
\[
\widehat{\mathcal{L}}_\phi(x)
 = \tfrac{1}{n(n-1)}\!\!\sum_{i\neq j}\!\! k(f_\phi(x,\eta_i), f_\phi(x,\eta_j))
 + \tfrac{1}{m(m-1)}\!\!\sum_{i\neq j}\!\! k(\tilde y_i, \tilde y_j)
 - \tfrac{2}{nm}\!\!\sum_{i,j}\!\! k(f_\phi(x,\eta_i), \tilde y_j).
\]
By Assumption~\ref{ass:kernel}(i) each kernel evaluation lies in
$[0, K_{\max}]$, so changing one of its arguments shifts that
evaluation by at most $K_{\max}$.  We compute the bounded-difference
constants for McDiarmid's inequality applied to
$\widehat{\mathcal{L}}_\phi$ as a function of the $n+m$ independent
variables $\eta_1,\ldots,\eta_n,\tilde y_1,\ldots,\tilde y_m$.
Replacing $\eta_i$ (which sets $Y_i = f_\phi(x,\eta_i)$) leaves the
$\tilde y$-only term unchanged and affects only:
\begin{itemize}
\item the within-$Y$ term, in which $Y_i$ appears in the $2(n-1)$
ordered pairs $(i,j)$ and $(j,i)$ for $j\neq i$, each with coefficient
$\tfrac{1}{n(n-1)}$ and per-pair shift at most $K_{\max}$, contributing
$\tfrac{2(n-1)\cdot K_{\max}}{n(n-1)}=\tfrac{2K_{\max}}{n}$;
\item the cross term, in which $Y_i$ appears in $m$ pairs $(i,j)$
each with coefficient $\tfrac{2}{nm}$ and per-pair shift at most
$K_{\max}$, contributing $\tfrac{m\cdot 2 K_{\max}}{nm}=\tfrac{2K_{\max}}{n}$.
\end{itemize}
Summing, the bounded-difference constant for an $\eta_i$-change is
$c_\eta = \tfrac{4K_{\max}}{n}$. By the symmetric argument,
$c_{\tilde y} = \tfrac{4K_{\max}}{m}$.  Hence
$\sum_{i=1}^{n} c_\eta^2 + \sum_{j=1}^{m} c_{\tilde y}^2
 = 16\,K_{\max}^2\,(1/n + 1/m)$,
and McDiarmid's inequality~\citep{mcdiarmid1989method} gives, for any $t \ge 0$,
\[
  \mathbb{P}\!\bigl(|T_1| \ge t\bigr)
    \;\le\;
    2\exp\!\left(-\tfrac{t^2}{8K_{\max}^2\,(1/n + 1/m)}\right);
\]
equivalently, with probability at least $1 - \delta$,
\begin{equation}
  |T_1| \;\le\;
    K_{\max}\sqrt{8\,\log(2/\delta)\,(1/n + 1/m)}
    \;\le\;
    2\sqrt{2}\,K_{\max}\!\left(\sqrt{\tfrac{\log(2/\delta)}{n}}
                              + \sqrt{\tfrac{\log(2/\delta)}{m}}\right),
  \label{eq:loss-mc}
\end{equation}
where the second inequality uses $\sqrt{a+b}\le\sqrt{a}+\sqrt{b}$.

\emph{Step 2: Distillation term.}
For a distribution $\mathcal{Q}$ on $\mathcal{Y}$ write
$\mu_\mathcal{Q} := \mathbb{E}_{Y\sim\mathcal{Q}}[\varphi_k(Y)]
   \in \mathcal{H}_k$ for its kernel mean embedding. For any
positive-definite kernel $k$ and any two
distributions $\mathcal{Q}_1, \mathcal{Q}_2$,
$\operatorname{MMD}(\mathcal{Q}_1, \mathcal{Q}_2)
  = \|\mu_{\mathcal{Q}_1} - \mu_{\mathcal{Q}_2}\|_{\mathcal{H}_k}$,\footnote{This RKHS-norm identity does not require characteristicness; the characteristic clause of Assumption~\ref{ass:kernel} is used only for the identifiability part of Corollary~\ref{cor:lowrank}.}
and $\|\mu_\mathcal{Q}\|_{\mathcal{H}_k} \le \sqrt{K_{\max}}$ for any
$\mathcal{Q}$. The reverse triangle inequality then gives
\begin{equation}
 \bigl|\operatorname{MMD}(\mathcal{P}_\phi, \mathcal{G})
    - \operatorname{MMD}(\mathcal{P}, \mathcal{G})\bigr|
   \;\le\;
   \|\mu_{\mathcal{P}_\phi} - \mu_{\mathcal{P}}\|_{\mathcal{H}_k}.
 \label{eq:loss-reverse-tri}
\end{equation}
Let $(Y, \tilde Y)$ be any coupling of $\mathcal{P}$ and
$\mathcal{P}_\phi$. Jensen's inequality in $\mathcal{H}_k$ and the
Lipschitz feature map (Assumption~\ref{ass:kernel}(ii)) yield
\[
  \|\mu_{\mathcal{P}_\phi} - \mu_{\mathcal{P}}\|_{\mathcal{H}_k}
    = \bigl\|\mathbb{E}\!\bigl[\varphi_k(\tilde Y) - \varphi_k(Y)\bigr]
                                  \bigr\|_{\mathcal{H}_k}
    \;\le\; \mathbb{E}\|\varphi_k(\tilde Y) - \varphi_k(Y)\|_{\mathcal{H}_k}
    \;\le\; L_k\,\mathbb{E}\|\tilde Y - Y\|.
\]
Taking the infimum over couplings gives
$\|\mu_{\mathcal{P}_\phi} - \mu_{\mathcal{P}}\|_{\mathcal{H}_k}
 \le L_k\, W_1(\mathcal{P}_\phi, \mathcal{P})
 \le L_k\, W_2(\mathcal{P}_\phi, \mathcal{P})
 \le L_k\,\varepsilon_s$
by Assumption~\ref{ass:samples}. Substituting
into~\eqref{eq:loss-reverse-tri} and using $|a^2 - b^2| \le (a+b)|a-b|$
with $a, b \le 2\sqrt{K_{\max}}$ (each MMD is at most twice the maximal
embedding norm),
\begin{equation}
  T_2 \;\le\; 4\sqrt{K_{\max}}\cdot L_k\,\varepsilon_s
        \;=:\; C_2\,\varepsilon_s.
  \label{eq:loss-dist}
\end{equation}

Combining~\eqref{eq:loss-mc}, \eqref{eq:loss-dist}
and~\eqref{eq:loss-triangle} gives the stated bound with probability
at least $1 - \delta$.

\begin{align}
\nabla_x \mathcal{L}_\phi - \nabla_x \mathcal{L}
&= 2\langle u + v, \nabla_x(u+v)\rangle_{\mathcal{H}_k}
   - 2\langle v, \nabla_x v\rangle_{\mathcal{H}_k}\notag\\
&= 2\langle u, \nabla_x u\rangle_{\mathcal{H}_k}
   + 2\langle u, \nabla_x v\rangle_{\mathcal{H}_k}
   + 2\langle v, \nabla_x u\rangle_{\mathcal{H}_k}.
\label{eq:grad-decomp}
\end{align}

